-- D1 enforces foreign keys according to its database configuration.
CREATE TABLE IF NOT EXISTS User (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, email TEXT, passwordHash TEXT NOT NULL, displayName TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'MEMBRE', active INTEGER NOT NULL DEFAULT 1, memberId TEXT UNIQUE REFERENCES Member(id) ON DELETE SET NULL, lastLoginAt TEXT, createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS Member (id TEXT PRIMARY KEY, memberNumber TEXT NOT NULL UNIQUE, name TEXT NOT NULL, phone TEXT, email TEXT, address TEXT, note TEXT, birthdate TEXT, birthplace TEXT, profession TEXT, position TEXT, joinedOn TEXT, asblStatus TEXT, forumStatus TEXT, meetingStatus TEXT, photoUrl TEXT, birthdayVisible INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'active', createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS MonthlyContribution (id TEXT PRIMARY KEY, memberId TEXT NOT NULL, contributionYear INTEGER NOT NULL, contributionMonth INTEGER NOT NULL CHECK(contributionMonth BETWEEN 1 AND 12), amount REAL NOT NULL CHECK(amount >= 0), currency TEXT NOT NULL DEFAULT 'CDF', note TEXT, paidAt TEXT, recordedBy TEXT, createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(memberId, contributionYear, contributionMonth), FOREIGN KEY(memberId) REFERENCES Member(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS MemberPayment (id TEXT PRIMARY KEY, memberId TEXT NOT NULL, paymentYear INTEGER NOT NULL, paymentMonth INTEGER NOT NULL CHECK(paymentMonth BETWEEN 1 AND 12), paid INTEGER NOT NULL DEFAULT 0, updatedBy TEXT, updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(memberId, paymentYear, paymentMonth), FOREIGN KEY(memberId) REFERENCES Member(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS TontinePeriod (id TEXT PRIMARY KEY, title TEXT NOT NULL, startsOn TEXT NOT NULL, endsOn TEXT NOT NULL, contributionAmount REAL NOT NULL CHECK(contributionAmount >= 0), currency TEXT NOT NULL DEFAULT 'CDF', status TEXT NOT NULL DEFAULT 'open', createdById TEXT, createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS TontineEntry (id TEXT PRIMARY KEY, periodId TEXT NOT NULL, memberId TEXT NOT NULL, amount REAL NOT NULL, currency TEXT NOT NULL DEFAULT 'CDF', status TEXT NOT NULL DEFAULT 'due', paidAt TEXT, recordedBy TEXT, createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(periodId, memberId), FOREIGN KEY(periodId) REFERENCES TontinePeriod(id) ON DELETE CASCADE, FOREIGN KEY(memberId) REFERENCES Member(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS AidRequest (id TEXT PRIMARY KEY, memberId TEXT NOT NULL, subject TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'submitted', decisionNote TEXT, decidedBy TEXT, decidedAt TEXT, createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(memberId) REFERENCES Member(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS Post (id TEXT PRIMARY KEY, authorId TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'annonce', status TEXT NOT NULL DEFAULT 'published', createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(authorId) REFERENCES User(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS PostComment (id TEXT PRIMARY KEY, postId TEXT NOT NULL, authorId TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'published', createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(postId) REFERENCES Post(id) ON DELETE CASCADE, FOREIGN KEY(authorId) REFERENCES User(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS MediaItem (id TEXT PRIMARY KEY, authorId TEXT NOT NULL, title TEXT NOT NULL, description TEXT, mediaType TEXT NOT NULL, dataUrl TEXT, externalUrl TEXT, isPublic INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'published', createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(authorId) REFERENCES User(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS AuditLog (id TEXT PRIMARY KEY, actorId TEXT, actorName TEXT, action TEXT NOT NULL, entity TEXT NOT NULL, entityId TEXT, details TEXT, createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actorId) REFERENCES User(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_member_name ON Member(name);
CREATE INDEX IF NOT EXISTS idx_contribution_year_month ON MonthlyContribution(contributionYear, contributionMonth);
CREATE INDEX IF NOT EXISTS idx_post_status_created ON Post(status, createdAt);
CREATE INDEX IF NOT EXISTS idx_aid_status_created ON AidRequest(status, createdAt);

CREATE TABLE IF NOT EXISTS LoginAttempt (id TEXT PRIMARY KEY, username TEXT NOT NULL, ip TEXT NOT NULL, createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_login_attempt_user_ip_time ON LoginAttempt(username,ip,createdAt);
